import{_ as s,l,o as e,c as i,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"吊销与 OCSP","description":"","frontmatter":{"title":"吊销与 OCSP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cert-revoke.md","filePath":"cs/cert-revoke.md","lastUpdated":1789023840000}'),h={name:"cs/cert-revoke.md"};function _(C,a,E,A,P,S){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="吊销与-ocsp" tabindex="-1">吊销与 OCSP <a class="header-anchor" href="#吊销与-ocsp" aria-label="Permalink to &quot;吊销与 OCSP&quot;">​</a></h1><div class="epigraph"><p>证书在有效期内私钥仍可能泄露；吊销列表与在线状态协议把「现在还信不信这张证」从签发时拆出来。</p><footer>—— 据 RFC 5280 对 CRL；OCSP；Anderson 对 PKI 失败模式的整理</footer></div><p><a href="/cs/cert-pki">上一课</a>给出根锚、链与「信任是对签发者」。本课不重做 X.509 字段。缺口是时间：未到期不等于仍安全。CRL 批量发布已吊销序号；OCSP 问一张证的状态。口令课是人的秘密，下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PKI 课留下链。私钥丢失、名称绑错、CA 被逼签发，都要求在 notAfter 之前作废。浏览器若跳过吊销检查，中间人仍可持一张「看起来未过期」的证。缺口是<strong>状态查询合同</strong>：离线 CRL 与在线 OCSP，以及软失败（查不到就放行）如何把规格掏空。</p><p><span class="marginnote">OCSP stapling 把应答钉在服务器握手里，减轻隐私与可达性问题。CRL 体积是运营代价。本课不写攻击者如何骗过软失败。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>签发者维护吊销信息。客户端：链验证通过后查状态，失败则拒绝。缓存要短，以免吊销延迟。短寿命证书把吊销换成「很快过期」，是另一政策。本课只钉检查点，不选厂商策略。</p>',8)),(e(),n(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHAIN%5B%22%E9%93%BE%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%22%5D%20--%3E%20STAT%5B%22%E6%9F%A5%20CRL%20%E6%88%96%20OCSP%22%5D%0A%20%20STAT%20--%3E%20OK%5B%22%E4%BB%8D%E6%9C%89%E6%95%88%E5%88%99%E7%94%A8%E5%85%AC%E9%92%A5%22%5D%0A%20%20STAT%20--%3E%20REV%5B%22%E5%B7%B2%E5%90%8A%E9%94%80%E5%88%99%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>吊销把 PKI 从静态文件变成带时间的系统。它服务真实性：名字与密钥的绑定可被撤回。与 <a href="/cs/tls-handshake">TLS 握手</a> 的关系：握手必须消费新鲜状态，否则证书课白讲。后课口令是另一身份源，不替代服务器证书。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把证书透明日志的全部八卦当主干。人如何证明自己，下一课口令与加盐。</p><p>后课默认：有效期不够，还要状态。人的秘密用盐存哈希。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>吊销把证书从「未过期」里再砍一刀。</li><li>CRL 批量，OCSP 按张；软失败会取消这层。</li><li>口令存储下一课。</li><li>出处：RFC 5280；Anderson；Stallings。</li></ul>',7))])}const u=s(h,[["render",_]]);export{f as __pageData,u as default};
